SELECT ?film ?filmLabel ?director ?directorLabel ?bd ?abs ?birthYear WHERE {
  VALUES ?film { dbr:Shadow_of_the_Earth dbr:Wolves_of_the_Range }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:birthDate ?bd }
  OPTIONAL { ?director dbo:abstract ?abs FILTER(langMatches(lang(?abs), "en")) }
  BIND(
    IF(bound(?bd),
       YEAR(?bd),
       xsd:integer(
         SUBSTR(
           STRBEFORE(STRAFTER(?abs, "("), " –"),
           STRLEN(STRBEFORE(STRAFTER(?abs, "("), " –")) - 3,
           4
         )
       )
    ) AS ?birthYear
  )
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER(langMatches(lang(?filmLabel), "en")) }
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER(langMatches(lang(?directorLabel), "en")) }
} ORDER BY ?birthYear

